import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const e="/img/math-arithmetic-sequence-1.svg",g=JSON.parse('{"title":"奥数思维：等差数列的认识与计算初步","description":"从 1, 3, 5 到 2, 5, 8，这些按固定间距“跳跃”的数字串就是等差数列。本文带你认识等差数列的三个核心成员，掌握求任意一项的万能公式。","frontmatter":{"title":"奥数思维：等差数列的认识与计算初步","date":"2026-02-16T10:00:00.000Z","categories":["数学"],"tags":["小学奥数","等差数列","数列规律","基础逻辑"],"description":"从 1, 3, 5 到 2, 5, 8，这些按固定间距“跳跃”的数字串就是等差数列。本文带你认识等差数列的三个核心成员，掌握求任意一项的万能公式。","cover":"/img/math-arithmetic-sequence-1.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-arithmetic-sequence-1.md","filePath":"posts/primary-math-olympiad-arithmetic-sequence-1.md","lastUpdated":null}'),p={name:"posts/primary-math-olympiad-arithmetic-sequence-1.md"};function l(o,a,r,i,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="奥数思维-等差数列的认识与计算初步" tabindex="-1">奥数思维：等差数列的认识与计算初步 <a class="header-anchor" href="#奥数思维-等差数列的认识与计算初步" aria-label="Permalink to &quot;奥数思维：等差数列的认识与计算初步&quot;">​</a></h1><p>你有没有观察过家里楼梯的台阶？每一级台阶的高度都是一样的。</p><p>在数学里，如果一串数字，从第二项起，每一项与它前一项的<strong>差</strong>都是同一个常数，我们就管它叫**“等差数列”**。这种规律性极强的数列，是奥数中非常重要的基础知识。</p><hr><h2 id="一、-认识等差数列的-三剑客" tabindex="-1">一、 认识等差数列的“三剑客” <a class="header-anchor" href="#一、-认识等差数列的-三剑客" aria-label="Permalink to &quot;一、 认识等差数列的“三剑客”&quot;">​</a></h2><p>要玩转等差数列，你必须认识这三个核心成员：</p><p><img src="'+e+'" alt="等差数列模型图解"></p><ol><li><strong>首项（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>a</mi><mn>1</mn></msub></mrow><annotation encoding="application/x-tex">a_1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.58056em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">a</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathrm">1</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>）</strong>：数列里的第一个数。</li><li><strong>公差（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>d</mi></mrow><annotation encoding="application/x-tex">d</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">d</span></span></span></span>）</strong>：相邻两个数之间“跳跃”的距离（也就是那个不变的差）。</li><li><strong>项数（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span>）</strong>：这个数列里一共有多少个数。</li></ol><hr><h2 id="二、-核心公式-寻找第-个数" tabindex="-1">二、 核心公式：寻找第 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span> 个数 <a class="header-anchor" href="#二、-核心公式-寻找第-个数" aria-label="Permalink to &quot;二、 核心公式：寻找第 $n$ 个数&quot;">​</a></h2><p>如果我们知道第一个数和每次跳多远，怎么求第 100 个数呢？</p><p><strong>【通项公式】</strong>：</p><blockquote><p><strong>第 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span> 项 = 首项 + (项数 - 1) × 公差</strong></p></blockquote><p><strong>为什么是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(n-1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">n</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span>？</strong> 想象你要跳到第 4 级台阶，你只需要跳 <strong>3 次</strong>（从 1 到 2，从 2 到 3，从 3 到 4）。所以，间隔数永远比项数少 1。</p><p><strong>【例题 1】</strong>： 等差数列：2, 5, 8, 11 \\dots 请问第 10 项是多少？ <strong>解析</strong>：</p><ol><li>首项 = 2</li><li>公差 = 3（<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">5 - 2 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span>）</li><li>项数 = 10 <strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>+</mo><mo>(</mo><mn>1</mn><mn>0</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>×</mo><mn>3</mn><mo>=</mo><mn>2</mn><mo>+</mo><mn>2</mn><mn>7</mn><mo>=</mo><mn>2</mn><mn>9</mn></mrow><annotation encoding="application/x-tex">2 + (10 - 1) \\times 3 = 2 + 27 = 29</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">9</span></span></span></span>。 <strong>答案</strong>：29。</li></ol><hr><h2 id="三、-逆向思维-求它是第几个" tabindex="-1">三、 逆向思维：求它是第几个 <a class="header-anchor" href="#三、-逆向思维-求它是第几个" aria-label="Permalink to &quot;三、 逆向思维：求它是第几个&quot;">​</a></h2><p><strong>【项数公式】</strong>：</p><blockquote><p><strong>项数 = (末项 - 首项) ÷ 公差 + 1</strong></p></blockquote><p><strong>【例题 2】</strong>： 数列 3, 7, 11, 15 \\dots 39。这个数列一共有多少项？ <strong>解析</strong>：</p><ol><li>首项 = 3，末项 = 39，公差 = 4。</li><li>间距总长度：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>9</mn><mo>−</mo><mn>3</mn><mo>=</mo><mn>3</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">39 - 3 = 36</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">9</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span></span></span></span>。</li><li>间隔个数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>6</mn><mo>÷</mo><mn>4</mn><mo>=</mo><mn>9</mn></mrow><annotation encoding="application/x-tex">36 \\div 4 = 9</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mbin">÷</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">9</span></span></span></span>（个）。</li><li>项数（树比间隔多 1）：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">9 + 1 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>（个）。 <strong>答案</strong>：10 项。</li></ol><hr><h2 id="四、-避坑指南-分清-项-和-间隔" tabindex="-1">四、 避坑指南：分清“项”和“间隔” <a class="header-anchor" href="#四、-避坑指南-分清-项-和-间隔" aria-label="Permalink to &quot;四、 避坑指南：分清“项”和“间隔”&quot;">​</a></h2><p>这是最容易出错的地方！</p><ul><li><strong>记住</strong>：项数就像是路边的树，公差就像是树与树之间的距离。</li><li><strong>植树原则</strong>：两端都种时，树 = 间隔 + 1。</li></ul><hr><h2 id="五、-练一练-数列小专家" tabindex="-1">五、 练一练（数列小专家） <a class="header-anchor" href="#五、-练一练-数列小专家" aria-label="Permalink to &quot;五、 练一练（数列小专家）&quot;">​</a></h2><ol><li><strong>基础关</strong>：已知等差数列首项是 1，公差是 2。请写出前 5 项。</li><li><strong>进阶关</strong>：数列 1, 4, 7, 10 \\dots 的第 20 项是多少？</li><li><strong>挑战关</strong>：数列 5, 10, 15 \\dots 100 一共有多少个数？</li></ol><hr><p><em>总结：等差数列就是一场有节奏的“数字接力”。抓住了首项和公差这两个关键，你就能精准定位每一个数字的位置！</em></p>',31)])])}const u=s(p,[["render",l]]);export{g as __pageData,u as default};
